package br.com.sussmartcare.patientregistry.domain;
import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="patients") public class Patient { @Id private UUID id; @Column(nullable=false) private String fullName; private LocalDate birthDate; @Enumerated(EnumType.STRING) @Column(nullable=false) private IdentityStatus identityStatus; @Column(nullable=false) private Instant createdAt; private UUID mergedIntoPatientId;
 protected Patient(){} public Patient(UUID id,String fullName,LocalDate birthDate,IdentityStatus status){this.id=id;this.fullName=Objects.requireNonNull(fullName);this.birthDate=birthDate;this.identityStatus=Objects.requireNonNull(status);this.createdAt=Instant.now();}
 public static Patient provisional(String description){return new Patient(UUID.randomUUID(),description,null,IdentityStatus.PROVISIONAL);} public void confirmIdentity(String fullName,LocalDate birthDate){this.fullName=Objects.requireNonNull(fullName);this.birthDate=birthDate;this.identityStatus=IdentityStatus.CONFIRMED;} public void mergeInto(UUID canonical){if(canonical.equals(id)) throw new IllegalArgumentException("Paciente não pode ser mesclado consigo mesmo"); this.identityStatus=IdentityStatus.MERGED;this.mergedIntoPatientId=canonical;}
 public UUID getId(){return id;} public String getFullName(){return fullName;} public LocalDate getBirthDate(){return birthDate;} public IdentityStatus getIdentityStatus(){return identityStatus;} public Instant getCreatedAt(){return createdAt;} public UUID getMergedIntoPatientId(){return mergedIntoPatientId;}
}